import React, { useState } from 'react';
import Card from '../components/Card';

const ExpenseCalculator = ({ user }) => {
  const [income, setIncome] = useState('');
  const [expenses, setExpenses] = useState([{ category: '', amount: '' }]);
  const [totalExpense, setTotalExpense] = useState(0);
  const [savings, setSavings] = useState(0);
  const [message, setMessage] = useState('');

  const calculateExpenses = () => {
    const total = expenses.reduce((sum, item) => sum + parseFloat(item.amount || 0), 0);
    setTotalExpense(total);
    
    if (income) {
      const calculatedSavings = parseFloat(income) - total;
      setSavings(calculatedSavings);
      setMessage(calculatedSavings >= 0 
        ? `You can save ₹${calculatedSavings.toFixed(2)} this month!` 
        : `You're overspending by ₹${Math.abs(calculatedSavings).toFixed(2)}!`
      );
    }
  };

  const saveExpenses = async () => {
    try {
      await Promise.all(expenses.map(expense => {
        if (expense.category && expense.amount) {
          return fetch('http://localhost:5000/api/expense/expense', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              userId: user.id,
              amount: expense.amount,
              category: expense.category,
              description: `Expense for ${expense.category}`
            })
          });
        }
        return Promise.resolve();
      }));
      setMessage('Expenses saved successfully!');
    } catch (err) {
      setMessage('Failed to save expenses');
    }
  };

  return (
    <div className="card">
      <h2>Expense Calculator</h2>
      <input
        type="number"
        placeholder="Amount"
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
      />
      <input
        type="text"
        placeholder="Category"
        value={category}
        onChange={(e) => setCategory(e.target.value)}
      />
      <div className="button-group">
        <button className="btn-primary" onClick={handleCalculate}>Calculate</button>
        <button className="btn-secondary" onClick={handleSave}>Save</button>
      </div>
      <h3>Total Expense: ₹{totalExpense}</h3>
    </div>
  );
}

export default ExpenseCalculator;
